SET LOCAL ROLE haven_finance_worker;
SELECT pg_temp.batch_error($q$SELECT public.start_finance_refresh(attempt) FROM cf$q$,'42501','identity-observer-loss-at-final-start-receipt-rolls-back');
RESET ROLE;
SELECT pg_temp.batch_assert((SELECT started_at IS NULL FROM public.finance_refresh_attempts WHERE id=(SELECT attempt FROM cf)),'failed-final-start-delivery-does-not-mark-started');
ROLLBACK TO SAVEPOINT final_start_identity_loss;
INSERT INTO bd SELECT 'start',public.start_finance_refresh(attempt) FROM cf;
SELECT pg_temp.batch_assert(document->>'status'='started' AND document#>>'{credential,refresh_token}'='SYNTHETIC_REFRESH_CANARY_342' AND length(document->>'completion_proof')=36,'start-first-delivery') FROM bd WHERE label='start';
SELECT pg_temp.batch_assert(current_setting('response.headers') LIKE '%no-store%','credential-no-store');
-- Immutable capture is a separate transaction boundary from validation/install.
RESET ROLE; SELECT pg_temp.worker_login('finance_capture'); SET LOCAL ROLE haven_finance_worker;
SELECT pg_temp.batch_error($q$SELECT public.capture_finance_refresh_candidate(attempt,response,'wrong',pg_temp.candidate_body()) FROM cf$q$,'42501','capture-wrong-completion-proof');
RESET ROLE;
CREATE FUNCTION pg_temp.reject_capture() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'SYNTHETIC_CAPTURE_ABORT_342'; END $$;
CREATE TRIGGER synthetic_capture_abort BEFORE INSERT ON public.finance_credential_candidates FOR EACH ROW EXECUTE FUNCTION pg_temp.reject_capture();
SET LOCAL ROLE haven_finance_worker;
SELECT pg_temp.batch_error($q$SELECT public.capture_finance_refresh_candidate(attempt,response,(SELECT document->>'completion_proof' FROM bd WHERE label='start'),pg_temp.candidate_body()) FROM cf$q$,'P0001','capture-final-write-injected-abort');
