SELECT pg_temp.batch_assert((SELECT count(*) FROM vault.secrets)=1 AND (SELECT count(*) FROM public.finance_credential_candidates)=1,'capture-abort-rolls-back-vault-and-metadata');
DROP TRIGGER synthetic_capture_abort ON public.finance_credential_candidates;
