SELECT public.capture_finance_refresh_candidate(attempt,response,(SELECT document->>'completion_proof' FROM bd WHERE label='start'),(pg_temp.candidate_body()::jsonb||'{"x_refresh_token_hard_expires_in":3600}')::text) FROM cf;
RESET ROLE; SELECT pg_temp.worker_login('finance_identity'); SET LOCAL ROLE haven_finance_worker;
INSERT INTO bd SELECT 'earlier_cap_identity',public.read_finance_credential_identity(gen_random_uuid(),response) FROM cf;
SELECT public.observe_finance_credential_identity(gen_random_uuid(),response,'123',repeat('a',64),'https://sandbox-quickbooks.api.intuit.com',repeat('d',64)) FROM cf;
RESET ROLE; SELECT pg_temp.worker_login('finance_install'); SET LOCAL ROLE haven_finance_worker;
SELECT public.install_finance_credential_candidate(response) FROM cf;
RESET ROLE;
SELECT pg_temp.batch_assert((SELECT r2.hard_expires_at=(SELECT started_at+interval '3600 seconds' FROM public.finance_refresh_attempts WHERE id=(SELECT attempt FROM cf)) AND r2.hard_expires_at<r1.hard_expires_at FROM public.finance_credential_revisions r1 JOIN public.finance_credential_revisions r2 ON r2.lineage_id=r1.lineage_id WHERE r1.revision=1 AND r2.revision=2),'earlier-reported-hard-cap-conservative-bound');
