INSERT INTO bd SELECT 'captured',public.capture_finance_refresh_candidate(attempt,response,(SELECT document->>'completion_proof' FROM bd WHERE label='start'),pg_temp.candidate_body()) FROM cf;
SELECT pg_temp.batch_assert((public.capture_finance_refresh_candidate(attempt,response,(SELECT document->>'completion_proof' FROM bd WHERE label='start'),pg_temp.candidate_body())->>'status')='protected_candidate_retained','capture-identical-replay-retains') FROM cf;
SELECT pg_temp.batch_error($q$SELECT public.capture_finance_refresh_candidate(attempt,response,(SELECT document->>'completion_proof' FROM bd WHERE label='start'),pg_temp.candidate_body()||' ') FROM cf$q$,'23505','capture-changed-response-conflict');
