INSERT INTO bd SELECT 'response_identity',public.read_finance_credential_identity(gen_random_uuid(),response) FROM cf;
SELECT pg_temp.batch_error($q$SELECT public.observe_finance_credential_identity(gen_random_uuid(),response,'999',repeat('a',64),'https://sandbox-quickbooks.api.intuit.com',repeat('d',64)) FROM cf$q$,'42501','wrong-company-observation-denied');
SELECT pg_temp.batch_error($q$SELECT public.observe_finance_credential_identity(gen_random_uuid(),response,'123',repeat('c',64),'https://sandbox-quickbooks.api.intuit.com',repeat('d',64)) FROM cf$q$,'42501','wrong-client-observation-denied');
SELECT pg_temp.batch_error($q$SELECT public.observe_finance_credential_identity(gen_random_uuid(),response,'123',repeat('a',64),'https://quickbooks.api.intuit.com',repeat('d',64)) FROM cf$q$,'42501','production-host-observation-denied');
SELECT public.observe_finance_credential_identity(gen_random_uuid(),response,'123',repeat('a',64),'https://sandbox-quickbooks.api.intuit.com',repeat('d',64)) FROM cf;
