CREATE OR REPLACE FUNCTION haven.finance_vault_read(p_id uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN RAISE EXCEPTION 'Protected credential store unavailable' USING ERRCODE='55000'; END $$;
