SELECT pg_temp.batch_error($q$SELECT public.install_finance_credential_candidate(response) FROM cf$q$,'55000','vault-outage-install-is-storage-failure');
RESET ROLE;
SELECT pg_temp.batch_assert(NOT EXISTS(SELECT 1 FROM public.finance_credential_receipts WHERE event='candidate_invalid'),'vault-outage-does-not-write-invalid-provider-evidence');
ROLLBACK TO SAVEPOINT protected_store_outage;
SAVEPOINT expired_hard_install;
RESET ROLE;
ALTER TABLE public.finance_credential_revisions DISABLE TRIGGER immutable_finance_credential_evidence;
UPDATE public.finance_credential_revisions SET hard_expires_at=clock_timestamp()-interval '1 second';
ALTER TABLE public.finance_credential_revisions ENABLE TRIGGER immutable_finance_credential_evidence;
SET LOCAL ROLE haven_finance_worker;
SELECT pg_temp.batch_assert(public.install_finance_credential_candidate(response)->>'status'='quarantined_expired','expired-known-hard-cap-blocks-install') FROM cf;
ROLLBACK TO SAVEPOINT expired_hard_install;
SAVEPOINT final_install_identity_loss;
RESET ROLE;
SELECT pg_temp.inject_observer_loss(response,'refresh_install') FROM cf;
CREATE TRIGGER loss_at_final_receipt BEFORE INSERT ON public.finance_credential_receipts FOR EACH ROW EXECUTE FUNCTION pg_temp.loss_at_receipt();
SET LOCAL ROLE haven_finance_worker;
SELECT pg_temp.batch_error($q$SELECT public.install_finance_credential_candidate(response) FROM cf$q$,'42501','identity-observer-loss-at-final-install-receipt-rolls-back');
RESET ROLE;
SELECT pg_temp.batch_assert((SELECT count(*) FROM public.finance_credential_revisions)=1,'failed-final-install-does-not-advance-revision');
ROLLBACK TO SAVEPOINT final_install_identity_loss;
SELECT pg_temp.batch_assert((public.install_finance_credential_candidate(response)->>'revision')='2','normal-refresh-install-CAS-revision') FROM cf;
SELECT pg_temp.batch_assert((public.install_finance_credential_candidate(response)->>'status')='installed_receipt','install-replay-no-double-revision') FROM cf;
RESET ROLE;
SELECT pg_temp.batch_assert((SELECT r2.hard_expires_at=r1.hard_expires_at AND r2.hard_expires_at IS NOT NULL FROM public.finance_credential_revisions r1 JOIN public.finance_credential_revisions r2 ON r2.lineage_id=r1.lineage_id WHERE r1.revision=1 AND r2.revision=2),'omitted-hard-cap-preserves-prior-deadline');
SELECT pg_temp.batch_assert((SELECT credential_revision=2 AND active_attempt_id IS NULL FROM public.finance_credential_lineages WHERE id=(SELECT (document->>'lineage_id')::uuid FROM bd WHERE label='binding')) AND (SELECT count(*) FROM public.finance_credential_revisions)=2,'single-active-revision-and-cleared-claim');
SELECT pg_temp.batch_assert(NOT EXISTS(SELECT 1 FROM public.finance_credential_receipts WHERE to_jsonb(finance_credential_receipts)::text LIKE '%CANARY_342%'),'no-canary-in-lifecycle-receipts');
SELECT pg_temp.batch_assert((SELECT bool_and(to_jsonb(c)::text NOT LIKE '%CANARY_342%') FROM public.finance_credential_candidates c),'no-canary-in-candidate-metadata');
SELECT pg_temp.worker_login('finance_refresh'); SET LOCAL ROLE haven_finance_worker;
SELECT pg_temp.batch_assert(public.start_finance_refresh(attempt)->>'status'='installed_receipt' AND public.start_finance_refresh(attempt)->>'credential_returned'='false','completed-start-replay-preserves-known-installed-outcome') FROM cf;
RESET ROLE;
SELECT pg_temp.batch_login('owner'); SET LOCAL ROLE authenticated;
SELECT pg_temp.batch_error($q$SELECT public.seed_finance_credential_candidate(gen_random_uuid(),entity,(public.finance_credential_status(entity)->>'lineage_id')::uuid,1,2,pg_temp.candidate_body()) FROM bf$q$,'42501','ready-credential-replacement-needs-explicit-reconnect');
SAVEPOINT staging_stopped_identity;
SELECT pg_temp.stage_stop(entity) FROM bf;
RESET ROLE; SELECT pg_temp.worker_login('finance_identity'); SET LOCAL ROLE haven_finance_worker;
SELECT pg_temp.batch_error($q$SELECT public.read_finance_credential_identity(gen_random_uuid(),response) FROM cf$q$,'42501','existing-staging-stop-fences-identity-read-by-context');
ROLLBACK TO SAVEPOINT staging_stopped_identity;
SAVEPOINT stopped_identity_read;
SELECT public.finance_credential_control(gen_random_uuid(),entity,'stop',jsonb_build_object('lineage_id',public.finance_credential_status(entity)->>'lineage_id','expected_fence_epoch',(public.finance_credential_status(entity)->>'fence_epoch')::bigint,'stopped',true)) FROM bf;
RESET ROLE; SELECT pg_temp.worker_login('finance_identity'); SET LOCAL ROLE haven_finance_worker;
SELECT pg_temp.batch_error($q$SELECT public.read_finance_credential_identity(gen_random_uuid(),response) FROM cf$q$,'42501','stop-fences-preexisting-identity-access-read');
SELECT pg_temp.batch_error($q$SELECT public.observe_finance_credential_identity(gen_random_uuid(),response,'123',repeat('a',64),'https://sandbox-quickbooks.api.intuit.com',repeat('d',64)) FROM cf$q$,'42501','stop-fences-preexisting-identity-observation');
ROLLBACK TO SAVEPOINT stopped_identity_read;
RESET ROLE;

SELECT pg_temp.batch_login('owner'); SET LOCAL ROLE authenticated;
SELECT pg_temp.batch_error($q$SELECT public.seed_finance_credential_candidate(gen_random_uuid(),entity,(public.finance_credential_status(entity)->>'lineage_id')::uuid,(public.finance_credential_status(entity)->>'connection_epoch')::bigint,(public.finance_credential_status(entity)->>'credential_revision')::bigint,pg_temp.candidate_body()) FROM bf$q$,'42501','independent-ready-reseed-denied');
SELECT public.finance_credential_control(gen_random_uuid(),entity,'stop',jsonb_build_object('lineage_id',public.finance_credential_status(entity)->>'lineage_id','expected_fence_epoch',(public.finance_credential_status(entity)->>'fence_epoch')::bigint,'stopped',true)) FROM bf;
RESET ROLE; SELECT pg_temp.worker_login('finance_identity'); SET LOCAL ROLE haven_finance_worker;
SELECT pg_temp.batch_error($q$SELECT public.read_finance_credential_identity(gen_random_uuid(),response) FROM cf$q$,'42501','independent-explicit-stop-read-denied');
RESET ROLE; SELECT pg_temp.batch_login('owner'); SET LOCAL ROLE authenticated;
SELECT public.finance_credential_control(gen_random_uuid(),entity,'reconnect',jsonb_build_object('lineage_id',public.finance_credential_status(entity)->>'lineage_id','expected_fence_epoch',(public.finance_credential_status(entity)->>'fence_epoch')::bigint,'app_config_sha256',repeat('d',64))) FROM bf;
SELECT pg_temp.batch_error($q$SELECT public.seed_finance_credential_candidate(gen_random_uuid(),entity,(public.finance_credential_status(entity)->>'lineage_id')::uuid,(public.finance_credential_status(entity)->>'connection_epoch')::bigint,(public.finance_credential_status(entity)->>'credential_revision')::bigint,pg_temp.candidate_body()) FROM bf$q$,'42501','independent-new-seed-while-reconnect-stopped-denied');
SELECT public.finance_credential_control(gen_random_uuid(),entity,'stop',jsonb_build_object('lineage_id',public.finance_credential_status(entity)->>'lineage_id','expected_fence_epoch',(public.finance_credential_status(entity)->>'fence_epoch')::bigint,'stopped',false)) FROM bf;
INSERT INTO bd SELECT 'independent_resumed_seed',public.seed_finance_credential_candidate(gen_random_uuid(),entity,(public.finance_credential_status(entity)->>'lineage_id')::uuid,(public.finance_credential_status(entity)->>'connection_epoch')::bigint,(public.finance_credential_status(entity)->>'credential_revision')::bigint,(pg_temp.candidate_body()::jsonb||'{"x_refresh_token_hard_expires_in":14400}')::text) FROM bf;
RESET ROLE; SELECT pg_temp.worker_login('finance_identity'); SET LOCAL ROLE haven_finance_worker;
INSERT INTO bd SELECT 'independent_resumed_identity',public.read_finance_credential_identity(gen_random_uuid(),(document->>'candidate_id')::uuid) FROM bd WHERE label='independent_resumed_seed';
SELECT public.observe_finance_credential_identity(gen_random_uuid(),(document->>'candidate_id')::uuid,'123',repeat('a',64),'https://sandbox-quickbooks.api.intuit.com',repeat('d',64)) FROM bd WHERE label='independent_resumed_seed';
RESET ROLE; SELECT pg_temp.worker_login('finance_install'); SET LOCAL ROLE haven_finance_worker;
SELECT pg_temp.batch_assert(public.install_finance_credential_candidate((document->>'candidate_id')::uuid)->>'status'='installed_sandbox','independent-explicit-resume-reconnect-bootstrap-succeeds') FROM bd WHERE label='independent_resumed_seed';
RESET ROLE;
SELECT pg_temp.batch_assert((SELECT r2.hard_expires_at IS NOT NULL AND r2.hard_expires_at=r1.hard_expires_at AND r3.hard_expires_at>r2.hard_expires_at AND r3.connection_epoch>r2.connection_epoch FROM public.finance_credential_revisions r1 JOIN public.finance_credential_revisions r2 ON r2.lineage_id=r1.lineage_id JOIN public.finance_credential_revisions r3 ON r3.lineage_id=r2.lineage_id WHERE r1.revision=1 AND r2.revision=2 AND r3.revision=3),'independent-hard-cap-preserved-until-explicit-reconnect');
SELECT pg_temp.batch_login('outsider'); SET LOCAL ROLE authenticated;
DO $$ BEGIN
 BEGIN
  PERFORM public.finance_credential_control(gen_random_uuid(),other_entity,'bind',pg_temp.declaration()) FROM bf;
 EXCEPTION WHEN OTHERS THEN
  IF SQLSTATE<>'42501' OR SQLERRM<>'Credential grant unavailable' THEN RAISE EXCEPTION 'Unexpected global grant denial'; END IF;
  PERFORM pg_temp.batch_assert(true,'independent-global-grant-denial-sanitized'); RETURN;
 END;
 RAISE EXCEPTION 'Duplicate grant ownership accepted';
END $$;
ROLLBACK;
